import java.io.BufferedReader;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.nextLine();
        try (FileWriter w = new FileWriter("{name}")) {
            for (int i = 0; i < n; i++) {
                w.write(sc.nextLine() + "\n");
            }
        }
        try (BufferedReader r = new BufferedReader(new FileReader("{name}"))) {
            int cnt = 0;
            String hang = r.readLine();
            while (hang != null) {
                cnt++;
                System.out.println("第 " + cnt + " 条：" + hang);
                hang = r.readLine();
            }
            System.out.println("册子上现在有 " + cnt + " 条");
        }
    }
}
